body.query:
fragment UserCore on User {
  id
  displayName
  friends(first: 50) { id displayName }
  orders(limit: 20) { id totalCents items(limit: 10) { quantity product { name priceCents } } }
}

fragment Wide on User {
  ...UserCore
  a: friends(first: 50) { ...UserCore }
  b: friends(first: 50) { ...UserCore }
  c: friends(first: 50) { ...UserCore }
}

query FragmentBomb {
  users(first: 50) { ...Wide }
}
